FROM RDS.FactCredentialAwards fact
JOIN RDS.DimCredentialIssuers CredentialIssuer
	ON fact.CredentialIssuerId = CredentialIssuer.DimCredentialIssuerId
JOIN RDS.DimCredentialDefinitions CredentialDefinition
	ON fact.CredentialDefinitionId = CredentialDefinition.DimCredentialDefinitionId
JOIN RDS.DimPeople CredentialAwardRecipientPerson
	ON fact.CredentialAwardRecipientPersonId = CredentialAwardRecipientPerson.DimPersonId
JOIN RDS.DimPeople_Current CredentialAwardRecipientPerson_Current
	ON fact.CredentialAwardRecipientPerson_CurrentId = CredentialAwardRecipientPerson_Current.DimPersonId
JOIN RDS.DimCredentialAwardStatuses CredentialAwardStatus
	ON fact.CredentialAwardStatusId = CredentialAwardStatus.DimCredentialAwardStatusId
JOIN RDS.DimSchoolYears SchoolYear
	ON fact.SchoolYearId = SchoolYear.DimSchoolYearId
JOIN RDS.DimCredentialAwards CredentialAward
	ON fact.CredentialAwardId = CredentialAward.DimCredentialAwardId
JOIN RDS.DimAssessments Assessment
	ON fact.AssessmentId = Assessment.DimAssessmentId
JOIN RDS.DimDataCollections DataCollection
	ON fact.DataCollectionId = DataCollection.DimDataCollectionId
JOIN RDS.DimK12Demographics K12Demographic
	ON fact.K12DemographicId = K12Demographic.DimK12DemographicId
